/* @socom-skeleton body Tick__6CInputFf */
void CInput::Tick(f32 dT)
{
	for (s32 pad = 0; pad < 2; pad++)
	{
		if (m_pads[pad] != NULL)
		{
			m_pads[pad]->Tick(dT);
		}
	}
}

/* @socom-skeleton body Flush__6CInputFv */
void CInput::Flush()
{
	for (s32 pad = 0; pad < 2; pad++)
	{
		if (m_pads[pad] != NULL)
		{
			m_pads[pad]->Flush();
		}
	}
}

